# =========================================================
# Figure 3: Complete solution rate
# =========================================================

def plot_solve_rate(rows):
    scenarios = [
        ("Reference 9x9", "reference_9x9", "propagation"),
        ("Reference 9x9", "reference_9x9", "full_solver"),
        ("Backtracking Demo", "backtracking_demo", "propagation"),
        ("Backtracking Demo", "backtracking_demo", "full_solver"),
    ]

    labels = []
    values = []

    for display_name, scenario, operation in scenarios:
        row = get_row(
            rows,
            scenario,
            operation,
        )

        labels.append(
            f"{display_name}\n{operation.replace('_', ' ').title()}"
        )

        values.append(
            float(row["solve_rate_percent"])
        )

    fig, ax = plt.subplots(figsize=(9, 5))

    bars = ax.bar(
        labels,
        values,
    )

    add_bar_labels(ax, bars, "%")

    ax.set_title(
        "Complete Solution Rate Across Kakuro Scenarios"
    )

    ax.set_ylabel("Solve rate (%)")
    ax.set_ylim(0, 115)

    ax.grid(
        axis="y",
        alpha=0.3,
    )

    ax.set_axisbelow(True)

    fig.tight_layout()

    save_figure(
        fig,
        "03_solve_rate.png",
    )


# =========================================================
# Figure 4: Mean number of pruned values
# =========================================================

def plot_pruned_values(rows):
    labels = [
        ("Reference 9x9", "reference_9x9", "propagation"),
        ("Reference 9x9", "reference_9x9", "full_solver"),
        ("Backtracking Demo", "backtracking_demo", "propagation"),
        ("Backtracking Demo", "backtracking_demo", "full_solver"),
    ]

    display_labels = []
    values = []

    for display_name, scenario, operation in labels:
        row = get_row(
            rows,
            scenario,
            operation,
        )

        display_labels.append(
            f"{display_name}\n{operation.replace('_', ' ').title()}"
        )

        values.append(
            float(row["mean_values_pruned"])
        )

    fig, ax = plt.subplots(figsize=(9, 5))

    bars = ax.bar(
        display_labels,
        values,
    )

    add_bar_labels(ax, bars, "")

    ax.set_title(
        "Mean Number of Domain Values Pruned"
    )

    ax.set_ylabel("Mean number of removed values")
    ax.set_ylim(0, max(values) * 1.2 + 1)

    ax.grid(
        axis="y",
        alpha=0.3,
    )

    ax.set_axisbelow(True)

    fig.tight_layout()

    save_figure(
        fig,
        "04_domain_pruning.png",
    )


# =========================================================
# Figure 5: Search activity on the demo puzzle
# =========================================================

def plot_search_activity(rows):
    propagation = get_row(
        rows,
        "backtracking_demo",
        "propagation",
    )

    full_solver = get_row(
        rows,
        "backtracking_demo",
        "full_solver",
    )

    metrics = [
        "Decisions",
        "Contradictions",
        "Backtracks",
    ]

    fields = [
        "mean_decisions",
        "mean_contradictions",
        "mean_backtracks",
    ]

    propagation_values = [
        float(propagation[field])
        for field in fields
    ]

    solver_values = [
        float(full_solver[field])
        for field in fields
    ]

    positions = list(range(len(metrics)))
    width = 0.35

    fig, ax = plt.subplots(figsize=(8, 4.8))

    bars1 = ax.bar(
        [position - width / 2 for position in positions],
        propagation_values,
        width,
        label="Constraint Propagation",
    )

    bars2 = ax.bar(
        [position + width / 2 for position in positions],
        solver_values,
        width,
        label="Full Solver",
    )

    ax.bar_label(
        bars1,
        labels=[f"{value:.2f}" for value in propagation_values],
        padding=3,
        fontsize=9,
    )

    ax.bar_label(
        bars2,
        labels=[f"{value:.2f}" for value in solver_values],
        padding=3,
        fontsize=9,
    )

    ax.set_xticks(
        positions,
        metrics,
    )

    ax.set_title(
        "Search Activity - Backtracking Demo"
    )

    ax.set_ylabel("Mean event count")

    ax.legend()

    ax.grid(
        axis="y",
        alpha=0.3,
    )

    ax.set_axisbelow(True)

    fig.tight_layout()

    save_figure(
        fig,
        "05_search_activity.png",
    )


# =========================================================
# Main
# =========================================================

def main():
    print("=" * 60)
    print("TASK 3 - BENCHMARK VISUALIZATION")
    print("=" * 60)

    rows = load_summary()

    print(f"Loaded {len(rows)} benchmark summary rows.")

    plot_reference_runtime(rows)
    plot_demo_runtime(rows)
    plot_solve_rate(rows)
    plot_pruned_values(rows)
    plot_search_activity(rows)

    print("\nAll figures generated successfully.")
    print(f"Output directory: {FIGURES_DIR}")


if __name__ == "__main__":
    main()
